import SwiftUI

struct Item: Identifiable {
    let id = UUID()
    var title: String
    var done: Bool
}

struct ChecklistView: View {
    @State private var items: [Item] = [
        Item(title: "Book the room", done: false),
        Item(title: "Send the agenda", done: true),
    ]

    var body: some View {
        List($items) { $item in
            ItemRow(item: $item)
        }
    }
}

struct ItemRow: View {
    @Binding var item: Item

    var body: some View {
        Toggle(item.title, isOn: $item.done)
    }
}
